-- pos-people-contact: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.event_outbox (
    id uuid NOT NULL,
    topic character varying(255) NOT NULL,
    record_key character varying(255) NOT NULL,
    payload text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    published_at timestamp(6) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text
);

CREATE TABLE public.party_postal_address (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    party_type character varying(20) NOT NULL,
    party_id uuid NOT NULL,
    line1 character varying(255) NOT NULL,
    line2 character varying(255),
    city character varying(120),
    region character varying(120),
    postal_code character varying(20),
    country_code character varying(2) NOT NULL,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    CONSTRAINT party_postal_address_party_type_check CHECK (((party_type)::text = ANY ((ARRAY['PERSON'::character varying, 'ORGANIZATION'::character varying])::text[])))
);

CREATE TABLE public.person (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    first_name character varying(255),
    last_name character varying(255),
    preferred_name character varying(255),
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone
);

CREATE TABLE public.person_contact_point (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    person_id uuid NOT NULL,
    contact_type character varying(20) NOT NULL,
    value character varying(255) NOT NULL,
    is_primary boolean NOT NULL,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    CONSTRAINT person_contact_point_contact_type_check CHECK (((contact_type)::text = ANY ((ARRAY['EMAIL'::character varying, 'PHONE_MOBILE'::character varying, 'PHONE_HOME'::character varying, 'PHONE_WORK'::character varying])::text[])))
);

CREATE TABLE public.processed_events (
    event_id character varying(36) NOT NULL,
    owner character varying(64) NOT NULL,
    processed_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.user_person_links (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    person_id uuid NOT NULL,
    username character varying(255) NOT NULL,
    status character varying(20) NOT NULL,
    link_type character varying(50),
    notes character varying(1000),
    created_by character varying(255),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone,
    CONSTRAINT user_person_links_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[])))
);

ALTER TABLE ONLY public.event_outbox
    ADD CONSTRAINT event_outbox_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.party_postal_address
    ADD CONSTRAINT party_postal_address_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.party_postal_address
    ADD CONSTRAINT party_postal_address_tenant_key UNIQUE (tenant_id, id);

ALTER TABLE ONLY public.person_contact_point
    ADD CONSTRAINT person_contact_point_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.person_contact_point
    ADD CONSTRAINT person_contact_point_tenant_key UNIQUE (tenant_id, id);

ALTER TABLE ONLY public.person
    ADD CONSTRAINT person_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.person
    ADD CONSTRAINT person_tenant_key UNIQUE (tenant_id, id);

ALTER TABLE ONLY public.processed_events
    ADD CONSTRAINT processed_events_pkey PRIMARY KEY (event_id);

ALTER TABLE ONLY public.party_postal_address
    ADD CONSTRAINT uq_party_postal_address_party UNIQUE (tenant_id, party_type, party_id);

ALTER TABLE ONLY public.user_person_links
    ADD CONSTRAINT user_person_links_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.user_person_links
    ADD CONSTRAINT user_person_links_tenant_key UNIQUE (tenant_id, id);

ALTER TABLE ONLY public.user_person_links
    ADD CONSTRAINT user_person_links_username_key UNIQUE (tenant_id, username);

CREATE INDEX idx_event_outbox_published_window ON public.event_outbox USING btree (topic, created_at) WHERE (published_at IS NOT NULL);

CREATE INDEX idx_event_outbox_unpublished ON public.event_outbox USING btree (id) WHERE (published_at IS NULL);

CREATE INDEX idx_party_postal_address_party ON public.party_postal_address USING btree (party_id);

CREATE INDEX idx_person_contact_point_person ON public.person_contact_point USING btree (person_id);

CREATE INDEX idx_person_contact_point_type ON public.person_contact_point USING btree (contact_type);

CREATE INDEX idx_processed_events_owner_event ON public.processed_events USING btree (owner, event_id);

CREATE INDEX idx_user_person_links_person_id ON public.user_person_links USING btree (person_id);

ALTER TABLE ONLY public.user_person_links
    ADD CONSTRAINT fk_user_person_links_person FOREIGN KEY (tenant_id, person_id) REFERENCES public.person(tenant_id, id);

CREATE INDEX party_postal_address_tenant_idx ON public.party_postal_address USING btree (tenant_id);

CREATE INDEX person_tenant_idx ON public.person USING btree (tenant_id);

CREATE INDEX person_contact_point_tenant_idx ON public.person_contact_point USING btree (tenant_id);

CREATE INDEX user_person_links_tenant_idx ON public.user_person_links USING btree (tenant_id);

ALTER TABLE public.party_postal_address ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.party_postal_address FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.party_postal_address
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());

ALTER TABLE public.person ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.person FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.person
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());

ALTER TABLE public.person_contact_point ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.person_contact_point FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.person_contact_point
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());

ALTER TABLE public.user_person_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_person_links FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.user_person_links
    USING (tenant_id = public.app_current_tenant())
    WITH CHECK (tenant_id = public.app_current_tenant());
